#!/usr/bin/env bash
# generate-spike.sh — Generate SPIKE_REPORT.md template
# Usage: ./generate-spike.sh --question "<research question>"

set -euo pipefail

QUESTION=""

while [[ $# -gt 0 ]]; do
  case "$1" in
    --question) QUESTION="$2"; shift 2 ;;
    *) echo "Unknown: $1"; exit 1 ;;
  esac
done

if [[ -z "$QUESTION" ]]; then
  echo "Usage: $0 --question \"<research question>\""
  exit 1
fi

OUTPUT="SPIKE_REPORT-$(date +%Y%m%d-%H%M%S).md"

cat > "$OUTPUT" << SPIKE
# Spike Report

## Research Question
$QUESTION

## Success Criteria
- [ ] Criterion 1
- [ ] Criterion 2

## Scope
**In scope:**
- [ ]

**Out of scope:**
- [ ]

**Timebox:** [hours]

## Sources Consulted
- [Source 1](url)
- [Source 2](url)

## Experiments
### Experiment 1: [Name]
- **Hypothesis:**
- **Method:**
- **Result:**
- **Conclusion:**

## Analysis

### Option A: [Name]
- **Pros:**
- **Cons:**
- **Risks:**

### Option B: [Name]
- **Pros:**
- **Cons:**
- **Risks:**

## Recommendation
[What we recommend and why]

## Confidence Level
🟢 High / 🟡 Medium / 🔴 Low

## Open Questions
- [ ]

## Next Steps
1. [ ]

---

*Generated by research-spike workflow*
SPIKE

echo "✅ Spike report generated: $OUTPUT"
